macro.command:
// Undead Fortitude - triggered on the isDamaged target pass
if (args[0].tag !== "TargetOnUse" || args[0].macroPass !== "isDamaged") return;
const di = workflow?.damageItem;
if (!di || di.oldHP < 1 || di.hpDamage <= 0) return;
// Only when this damage reduces the creature to 0 HP
if (di.newHP > 0) return;
// ...unless the damage is radiant or from a critical hit
if (workflow.isCritical || di.critical) return;
const isRadiant = (di.damageDetail ?? []).some(d => (d.type ?? "").toLowerCase() === "radiant");
if (isRadiant) return;

const name = macroItem?.name ?? "Undead Fortitude";
const dc = 5 + Math.max(0, di.totalDamage);
const flavor = `${name} - DC ${dc} Constitution saving throw`;
const save = (await actor.rollSavingThrow({ ability: "con", target: dc }, {}, { flavor, fastForward: true }))?.[0]?.total ?? 0;
if (save < dc) return; // failed the save - drops as normal

// Success: reduce the damage so exactly 1 HP remains.
const base = di.totalDamage;
MidiQOL.modifyDamageBy({ damageItem: di, value: (di.oldHP - 1) - base, type: "none", reason: name });
di.newHP = 1;
ChatMessage.create({
  speaker: ChatMessage.getSpeaker({ actor }),
  content: `<strong>${name}</strong>: ${actor.name} succeeds on a DC ${dc} Constitution save and drops to 1 hit point instead of 0.`
});
